command:
$ErrorActionPreference = 'Stop'
$token = $env:DCOIR_GITHUB_CL_TOKEN
if ([string]::IsNullOrWhiteSpace($token)) { $token = $env:DCOIR_GITHUB_FG_TOKEN }
if ([string]::IsNullOrWhiteSpace($token)) { throw 'No authorized GitHub token is available for workflow dispatch' }
$headers = @{ Authorization = "Bearer $token"; Accept = 'application/vnd.github+json'; 'X-GitHub-Api-Version' = '2022-11-28' }
$body = @{ ref = 'main' } | ConvertTo-Json -Compress
Invoke-RestMethod -Method Post -Uri 'https://api.github.com/repos/malwaredevil/dcoir-collector/actions/workflows/codeql-security.yml/dispatches' -Headers $headers -ContentType 'application/json' -Body $body | Out-Null
Write-Host 'CodeQL workflow_dispatch requested for main'
